    if (hasNum(p.living_area)) stats.push(["Living Area", fmtSqft(p.living_area), "property"]);
    if (hasNum(p.lot_sqft)) stats.push(["Lot Size", lotSize(p), "property"]);
    // Phase 52, derived from LND_SQFOOT - a unit conversion, not a second
